<style>body{font-family:system-ui,sans-serif;background:#f4f6f9;color:#172033;margin:0}main{max-width:1100px;margin:32px auto;padding:20px}.card{background:#fff;border:1px solid #dce3eb;border-radius:14px;padding:20px;margin-bottom:16px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px}.ok{color:#24683b;font-weight:800}.bad{color:#8e1f1f;font-weight:800}.warn{color:#8a5a0a;font-weight:800}.muted{color:#657389}.message,.error{padding:12px;border-radius:9px;margin-bottom:14px}.message{border:1px solid #8fb799}.error{border:1px solid #c99}button,.button{display:inline-block;padding:10px 14px;border:0;border-radius:9px;background:#172033;color:#fff;text-decoration:none;font-weight:700}input{padding:9px;border:1px solid #bac5d1;border-radius:8px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:9px;border-bottom:1px solid #edf0f4}.danger{background:#8e1f1f}</style></head><body><main>
